//#region src/lib/scoring.ts
/** Panel score weights: click 50%, stop (oprire) 30%, share 20%. */
var SCORE_WEIGHTS = {
	click: .5,
	stop: .3,
	share: .2
};
function computeMessageScore(m) {
	return Math.round(m.click * SCORE_WEIGHTS.click + m.stop * SCORE_WEIGHTS.stop + m.share * SCORE_WEIGHTS.share);
}
function passwordStrength(pw) {
	if (!pw) return 0;
	let s = 0;
	if (pw.length >= 8) s++;
	if (pw.length >= 12) s++;
	if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) s++;
	if (/\d/.test(pw) && /[^A-Za-z0-9]/.test(pw)) s++;
	return Math.min(4, s);
}
//#endregion
export { passwordStrength as n, computeMessageScore as t };
